// <live-value> — a single shared value that syncs across every client.
//
// The reinvention made concrete: shared state is just a published event on the
// room's channel (no CRDT, no provisioned KV) — set it here and it lands on every
// other client instantly, off the BEAM over RCP when a runtime is reachable, off
// the BroadcastChannel mock standalone. Last-write-wins with a logical clock
// (lamport-ish: max(seen)+1, ties broken by client id), which is the right floor;
// a workbook that needs convergence opts CRDT in per the live brief.
//
// It renders an inline control bound to the value and reflects remote changes
// live. Three shapes cover the common cases: counter, toggle, text.
//
// Attributes:
//   topic              bind directly (else inherits the nearest <live-room>)
//   name               the value's key on the channel (default "value")
//   variant = "counter" | "toggle" | "text"
//   label              caption shown beside the control
//   value              initial/local value (number|bool-ish|string per variant)
// Events:
//   work-value-change { name, value, from, local }   — on any change (local or remote)
// Property:  el.value  (get/set; setting publishes)
import { WbElement, html, css, define } from "../../core/element.js";
import { ref, createRef } from "lit/directives/ref.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";
import { clientId } from "./channel.js";
import { resolveChannel } from "./resolve.js";

const VARIANTS = defineVariants({
  variant: { options: ["counter", "toggle", "text"], default: "counter" },
});

export class WorkLiveValue extends WbElement {
  static variants = VARIANTS;
  static props = [...variantAttrs(VARIANTS), "topic", "name", "label", "value"];

  static properties = {
    ...WbElement.properties,
    _v: { state: true },   // the live value drives the Lit control
  };

  static styles = css`
    :host { display: inline-block; font-family: var(--work-font); color: var(--work-fg); }
    .box { display: inline-flex; align-items: center; gap: var(--work-space-3);
      border: 1px solid var(--work-border); border-radius: var(--work-radius);
      background: var(--work-surface); padding: var(--work-space-2) var(--work-space-3); }
    .label { font: 600 var(--work-text-sm) var(--work-font); color: var(--work-fg-muted); }
    .val { font: 700 var(--work-text-lg) var(--work-font-mono); color: var(--work-fg);
      min-width: 2ch; text-align: center; font-variant-numeric: tabular-nums;
      transition: color var(--work-dur) var(--work-ease); }
    .flash { animation: flash .5s var(--work-ease); }
    @keyframes flash { from { color: var(--work-brand) } to { color: var(--work-fg) } }
    button.step {
      width: 28px; height: 28px; flex: none; border-radius: var(--work-radius-sm);
      border: 1.5px solid var(--work-border-strong); background: var(--work-surface); color: var(--work-fg);
      font: 700 16px var(--work-font-mono); line-height: 1; cursor: pointer;
      transition: background var(--work-dur) var(--work-ease), transform var(--work-dur) var(--work-ease); }
    button.step:hover { background: var(--work-surface-soft); }
    button.step:active { transform: scale(.92); }

    .switch { position: relative; width: 44px; height: 26px; flex: none;
      border-radius: var(--work-radius-pill); background: var(--work-surface-soft);
      border: 1.5px solid var(--work-border-strong); cursor: pointer; padding: 0;
      transition: background var(--work-dur) var(--work-ease); }
    .switch[aria-checked="true"] { background: var(--work-brand); border-color: var(--work-brand); }
    .switch .knob { position: absolute; top: 1px; left: 1px; width: 20px; height: 20px;
      border-radius: 50%; background: var(--work-surface); box-shadow: var(--work-shadow-sm);
      transition: transform var(--work-dur) var(--work-ease); }
    .switch[aria-checked="true"] .knob { transform: translateX(18px); }

    input.text { font: var(--work-text) var(--work-font); color: var(--work-fg);
      background: var(--work-bg); border: 1.5px solid var(--work-border); border-radius: var(--work-radius-sm);
      padding: var(--work-space-2) var(--work-space-3); min-width: 16ch; }
    input.text:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--work-ring); border-color: var(--work-brand); }
  `;

  constructor() {
    super();
    this._valRef = createRef();
  }

  get key() { return this.attr("name", "value"); }

  get value() { return this._v; }
  set value(v) { this._apply(v, true); }

  connectedCallback() {
    super.connectedCallback();
    this._me = clientId();
    this._clock = 0;
    this._v = this._coerce(this.attr("value"));
    this._bind();
  }
  disconnectedCallback() { super.disconnectedCallback(); this._unsub?.(); this._reqUnsub?.(); }

  _coerce(raw) {
    const v = this.attr("variant", "counter");
    if (v === "counter") return Number(raw ?? 0) || 0;
    if (v === "toggle") return raw === "true" || raw === true || raw === "" ? true : false;
    return raw == null ? "" : String(raw);
  }

  _bind() {
    this._ch = resolveChannel(this);
    if (!this._ch) { requestAnimationFrame(() => { if (!this._ch) { this._bind(); this.requestUpdate(); } }); return; }
    this._unsub?.();
    // a single event channel namespaced by key
    this._unsub = this._ch.on("value:" + this.key, ({ payload, from }) => this._remote(payload, from));
    // ask the room for the current value once joined (a peer answers with its state)
    this._ch.publish("value:req", { key: this.key, from: this._me });
    this._reqUnsub = this._ch.on("value:req", ({ payload }) => {
      if (payload?.key === this.key) this._publish(); // answer with our state
    });
    this.requestUpdate();
  }

  _remote(payload, from) {
    if (!payload || payload.clock == null) return;
    // last-write-wins by logical clock, ties → higher client id
    if (payload.clock < this._clock) return;
    if (payload.clock === this._clock && from <= this._me) return;
    this._clock = payload.clock;
    this._apply(payload.value, false, from);
  }

  _apply(v, local, from) {
    this._v = v;
    if (local) { this._clock += 1; this._publish(); }
    this._flash();
    this.dispatchEvent(new CustomEvent("work-value-change", {
      bubbles: true, composed: true,
      detail: { name: this.key, value: this._v, from: local ? this._me : (from || "remote"), local: !!local },
    }));
  }

  _publish() { this._ch?.publish("value:" + this.key, { value: this._v, clock: this._clock, from: this._me }); }

  _flash() {
    // run after the reactive update paints the new value
    this.updateComplete.then(() => {
      const el = this._valRef.value;
      if (el) { el.classList.remove("flash"); void el.offsetWidth; el.classList.add("flash"); }
    });
  }

  render() {
    const v = this.attr("variant", "counter");
    const label = this.attr("label");
    const cap = label ? html`<span class="label">${label}</span>` : "";
    if (v === "toggle") {
      return html`<div class="box">${cap}<button class="switch" role="switch"
        aria-checked=${String(!!this._v)} part="switch"
        @click=${() => this._apply(!this._v, true)}><span class="knob"></span></button></div>`;
    }
    if (v === "text") {
      return html`<div class="box">${cap}<input class="text" part="input"
        .value=${String(this._v ?? "")} placeholder="type — syncs live"
        @input=${(e) => this._apply(e.target.value, true)} /></div>`;
    }
    return html`<div class="box">${cap}<button class="step dec" part="dec" aria-label="decrement"
      @click=${() => this._apply(Number(this._v) - 1, true)}>−</button><span class="val" part="value"
      ${ref(this._valRef)}>${Number(this._v) || 0}</span><button class="step inc" part="inc"
      aria-label="increment" @click=${() => this._apply(Number(this._v) + 1, true)}>+</button></div>`;
  }
}

define("live-value", WorkLiveValue);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}

// workponents · live domain — the channel seam (presence + pubsub).
//
// The reinvention: REALTIME IS A ROUTING CONFIG, not a provisioned backend.
// Presence/pubsub come FREE off the BEAM (Phoenix Presence + PubSub) over RCP
// through the Host socket seam — there is no separate realtime service to stand
// up, no Liveblocks/Pusher/Ably account, no schema. The elements bind to ONE
// small `Channel` abstraction layered on `this.host` (`host.socket(...)`). When a
// runtime is reachable it rides a real WebSocket to the BEAM; STANDALONE (no
// runtime) the SAME contract is served by a `BroadcastChannel` mock so the
// elements demo live — multiple tabs (or peers in one page) — with no backend.
//
// The elements never know which transport is live. That is the whole point: a
// `<live-room>` written against this seam works on a static page today and lights
// up against the runtime tomorrow with zero element changes — realtime as config.
//
// ────────────────────────────────────────────────────────────────────────────
// THE CONTRACT  (what every transport — real or mock — provides)
//
//   const ch = openChannel("room:design", { meta: { name, color } });
//   ch.join()                      → connects; resolves on first "joined"
//   ch.publish(event, payload)     → broadcast a message to the topic
//   ch.on(event, fn)               → subscribe to an event; returns unsubscribe
//   ch.track(meta)                 → set/update THIS client's presence metadata
//   ch.presence()                  → current presence list  [{ id, meta, online_at }]
//   ch.state                       → "idle" | "joining" | "joined" | "error" | "closed"
//   ch.leave() / ch.close()        → leave the topic / tear down
//
// Channel is an EventTarget. Lifecycle/data events (also reachable via `on`):
//   "state"     detail: { state }                       — connection state changed
//   "presence"  detail: { list, joins, leaves }         — presence set changed
//   "message"   detail: { event, payload, from, at }    — any published message
//   <event>     detail: { payload, from, at }           — a specific published event
//
// ────────────────────────────────────────────────────────────────────────────
// THE RUNTIME ENDPOINT SHAPE  (real transport — Phoenix over RCP)
//
//   host.socket("/live/" + topic, { onMessage })   → a WebSocket to the BEAM.
//   The runtime speaks a tiny Phoenix-flavored frame envelope (JSON):
//
//     client → server
//       { t: "join",     topic, ref, meta }            // enter + initial presence
//       { t: "track",    topic, ref, meta }            // update presence metadata
//       { t: "publish",  topic, ref, event, payload }  // broadcast to the topic
//       { t: "leave",    topic, ref }
//
//     server → client
//       { t: "joined",   topic, ref, presence }                    // ack + snapshot
//       { t: "presence", topic, joins, leaves, presence }          // Presence diff
//       { t: "message",  topic, event, payload, from, at }         // a broadcast
//       { t: "error",    topic, reason }
//
//   `presence` is the Phoenix Presence list mapped to [{ id, meta, online_at }].
//   `from` is the publisher's client id; `ref` correlates a client request to its
//   ack. A topic is any string ("room:<id>", "cursors:<doc>", "val:<key>"). This
//   maps 1:1 onto a Phoenix channel + Presence on the runtime — no new protocol.
//
// SUGGESTED CORE ADDITION (noted, not made): a first-class `host.channel(topic)`
// returning a `Channel` so every live element shares ONE connection per topic and
// the seam isn't re-derived per element. Until then we pool channels here, keyed
// by topic over the active Host.

import { getHost } from "../../core/host.js";

let _clientId = null;
/** A stable per-tab client id (presence identity for this browsing context). */
export function clientId() {
  if (_clientId) return _clientId;
  const k = "__wb_live_client__";
  try {
    _clientId = sessionStorage.getItem(k);
    if (!_clientId) {
      _clientId = "c_" + Math.random().toString(36).slice(2, 9) + Date.now().toString(36).slice(-3);
      sessionStorage.setItem(k, _clientId);
    }
  } catch {
    _clientId = "c_" + Math.random().toString(36).slice(2, 10);
  }
  return _clientId;
}

/** A deterministic, themeable color for a client id (presence dots/cursors). */
export function colorFor(id) {
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
  return `hsl(${h % 360} 68% 56%)`;
}

const now = () => Date.now();

/**
 * A presence/pubsub channel on a topic. Transport-agnostic: backed by a real
 * Host WebSocket when a runtime is reachable, else a same-machine BroadcastChannel
 * mock. Identical API + events either way.
 */
export class Channel extends EventTarget {
  /** @param {string} topic  @param {{ host?, meta?, mock?: boolean }} [opts] */
  constructor(topic, opts = {}) {
    super();
    this.topic = topic;
    this._host = opts.host || getHost();
    this._meta = opts.meta || {};
    this._id = clientId();
    this._mock = opts.mock != null ? opts.mock : !this._host.available?.("live");
    this._state = "idle";
    this._presence = new Map(); // id -> { id, meta, online_at }
    this._handlers = new Map(); // event -> Set<fn>
    this._ref = 0;
    this._transport = null;
  }

  get id() { return this._id; }
  get state() { return this._state; }
  get isMock() { return this._mock; }

  _setState(s) {
    if (this._state === s) return;
    this._state = s;
    this.dispatchEvent(new CustomEvent("state", { detail: { state: s } }));
  }

  /** Connect + announce presence. Resolves once joined. */
  join() {
    if (this._state === "joined" || this._state === "joining") return this._joinPromise || Promise.resolve();
    this._setState("joining");
    this._transport = this._mock ? new MockTransport(this) : new SocketTransport(this);
    this._joinPromise = new Promise((resolve) => { this._onJoined = resolve; });
    this._transport.start();
    return this._joinPromise;
  }

  /** Broadcast an event to everyone on the topic (self included by default). */
  publish(event, payload = {}) {
    const frame = { event, payload, from: this._id, at: now() };
    this._transport?.publish(frame);
    return frame;
  }

  /** Set/update THIS client's presence metadata; broadcast a presence diff. */
  track(meta = {}) {
    this._meta = { ...this._meta, ...meta };
    this._transport?.track(this._meta);
  }

  /** Subscribe to a published event (or "presence"/"state"/"message"). */
  on(event, fn) {
    if (event === "presence" || event === "state" || event === "message") {
      const h = (e) => fn(e.detail);
      this.addEventListener(event, h);
      return () => this.removeEventListener(event, h);
    }
    let set = this._handlers.get(event);
    if (!set) this._handlers.set(event, (set = new Set()));
    set.add(fn);
    return () => set.delete(fn);
  }

  /** Current presence list. */
  presence() {
    return [...this._presence.values()];
  }

  leave() {
    this._transport?.leave();
    this.close();
  }

  close() {
    this._transport?.close();
    this._transport = null;
    this._presence.clear();
    this._setState("closed");
  }

  // ── transport → channel callbacks (used by both transports) ──────────────
  _joined(presence) {
    this._ingestPresence(presence, true);
    this._setState("joined");
    this._onJoined?.();
  }

  _ingestPresence(list, replace = false) {
    const before = new Set(this._presence.keys());
    if (replace) this._presence.clear();
    for (const p of list || []) this._presence.set(p.id, p);
    const after = new Set(this._presence.keys());
    const joins = [...after].filter((x) => !before.has(x)).map((id) => this._presence.get(id));
    const leaves = [...before].filter((x) => !after.has(x)).map((id) => ({ id }));
    this.dispatchEvent(new CustomEvent("presence", { detail: { list: this.presence(), joins, leaves } }));
  }

  _presenceDiff({ joins = [], leaves = [] }) {
    for (const p of joins) this._presence.set(p.id, p);
    for (const l of leaves) this._presence.delete(l.id || l);
    this.dispatchEvent(new CustomEvent("presence", { detail: { list: this.presence(), joins, leaves } }));
  }

  _deliver({ event, payload, from, at }) {
    this.dispatchEvent(new CustomEvent("message", { detail: { event, payload, from, at } }));
    const set = this._handlers.get(event);
    if (set) for (const fn of set) fn({ payload, from, at });
  }

  _error(reason) {
    this._setState("error");
    this.dispatchEvent(new CustomEvent("message", { detail: { event: "error", payload: { reason }, from: "system", at: now() } }));
  }
}

// ── Real transport: a Host WebSocket to the BEAM (Phoenix Presence/PubSub) ────
class SocketTransport {
  constructor(channel) { this.ch = channel; this.ws = null; }
  start() {
    try {
      this.ws = this.ch._host.socket("/live/" + encodeURIComponent(this.ch.topic), {
        onMessage: (raw) => this._recv(raw),
      });
      this.ws.addEventListener("open", () => this._send({ t: "join", meta: this.ch._meta }));
      this.ws.addEventListener("error", () => this.ch._error("socket"));
      this.ws.addEventListener("close", () => { if (this.ch.state !== "closed") this.ch._setState("error"); });
    } catch (e) {
      // No runtime / socket refused → degrade to the mock so the UI still works.
      this.ch._mock = true;
      this.ch._transport = new MockTransport(this.ch);
      this.ch._transport.start();
    }
  }
  _ref() { return ++this.ch._ref; }
  _send(frame) {
    if (this.ws?.readyState === 1) this.ws.send(JSON.stringify({ topic: this.ch.topic, ref: this._ref(), ...frame }));
  }
  _recv(raw) {
    let m; try { m = typeof raw === "string" ? JSON.parse(raw) : raw; } catch { return; }
    switch (m.t) {
      case "joined": return this.ch._joined(m.presence || []);
      case "presence": return this.ch._presenceDiff({ joins: m.joins, leaves: m.leaves });
      case "message": return this.ch._deliver(m);
      case "error": return this.ch._error(m.reason);
    }
  }
  publish(frame) { this._send({ t: "publish", event: frame.event, payload: frame.payload }); }
  track(meta) { this._send({ t: "track", meta }); }
  leave() { this._send({ t: "leave" }); }
  close() { try { this.ws?.close(); } catch {} this.ws = null; }
}

// ── Mock transport: BroadcastChannel across tabs/peers on this machine ────────
// Mirrors the BEAM semantics: a shared bus + heartbeat-based presence so the
// elements demo true multi-participant presence with zero backend. Each tab is a
// distinct client; presence is reconstructed from periodic "hello" heartbeats and
// an explicit "bye" on unload — the same join/leave shape Phoenix Presence emits.
class MockTransport {
  constructor(channel) {
    this.ch = channel;
    this.bus = null;
    this._seen = new Map();   // id -> { id, meta, online_at, last }
    this._hb = null;
    this._gc = null;
  }
  _key() { return "wb-live:" + this.ch.topic; }
  start() {
    try { this.bus = new BroadcastChannel(this._key()); }
    catch { this.bus = new LocalBus(this._key()); } // very old/SSR fallback: self-only
    this.bus.addEventListener("message", (e) => this._recv(e.data));

    // announce + ask who's here
    this._self().online_at = now();
    this._post({ t: "hello", from: this.ch.id, meta: this.ch._meta, online_at: this._self().online_at });
    this._post({ t: "ping", from: this.ch.id });

    // seed our own presence immediately, then settle a snapshot
    this._note(this.ch.id, this.ch._meta, this._self().online_at);
    setTimeout(() => this.ch._joined([...this._seen.values()].map(({ id, meta, online_at }) => ({ id, meta, online_at }))), 60);

    this._hb = setInterval(() => this._post({ t: "hello", from: this.ch.id, meta: this.ch._meta, online_at: this._self().online_at }), 2500);
    this._gc = setInterval(() => this._sweep(), 1500);
    this._bye = () => this._post({ t: "bye", from: this.ch.id });
    window.addEventListener("pagehide", this._bye);
    window.addEventListener("beforeunload", this._bye);
  }
  _self() { return (this._me ||= { id: this.ch.id, online_at: now() }); }
  _post(m) { try { this.bus?.postMessage(m); } catch {} }
  _note(id, meta, online_at) {
    const had = this._seen.has(id);
    this._seen.set(id, { id, meta: meta || {}, online_at: online_at || now(), last: now() });
    if (!had && this.ch.state === "joined") this.ch._presenceDiff({ joins: [{ id, meta: meta || {}, online_at }], leaves: [] });
  }
  _drop(id) {
    if (this._seen.delete(id) && this.ch.state === "joined") this.ch._presenceDiff({ joins: [], leaves: [{ id }] });
  }
  _sweep() {
    const cutoff = now() - 7000;
    for (const [id, p] of this._seen) if (id !== this.ch.id && p.last < cutoff) this._drop(id);
  }
  _recv(m) {
    if (!m || m.from === this.ch.id) {
      // ignore our own broadcasts EXCEPT a peer's reply ping is from others
      if (m && m.t === "ping" && m.from === this.ch.id) return;
      if (m && m.from === this.ch.id) return;
    }
    switch (m.t) {
      case "hello": return this._note(m.from, m.meta, m.online_at);
      case "ping":  return this._post({ t: "hello", from: this.ch.id, meta: this.ch._meta, online_at: this._self().online_at });
      case "bye":   return this._drop(m.from);
      case "track": return this._note(m.from, m.meta, this._seen.get(m.from)?.online_at);
      case "pub":   return this.ch._deliver({ event: m.event, payload: m.payload, from: m.from, at: m.at });
    }
  }
  publish(frame) {
    // mock self-delivers so the publisher sees its own message (Phoenix default too)
    this.ch._deliver(frame);
    this._post({ t: "pub", from: this.ch.id, event: frame.event, payload: frame.payload, at: frame.at });
  }
  track(meta) {
    this._note(this.ch.id, meta, this._self().online_at);
    this._post({ t: "track", from: this.ch.id, meta });
  }
  leave() { this._bye?.(); }
  close() {
    clearInterval(this._hb); clearInterval(this._gc);
    window.removeEventListener("pagehide", this._bye);
    window.removeEventListener("beforeunload", this._bye);
    try { this.bus?.close?.(); } catch {}
    this.bus = null;
  }
}

// Minimal self-only bus for environments without BroadcastChannel.
class LocalBus extends EventTarget {
  postMessage() { /* self-only; no peers */ }
  close() {}
}

// ── Channel pool: one connection per topic over the active Host ───────────────
const _pool = new Map();

/** Get/open the shared channel for a topic (pooled per topic). */
export function openChannel(topic, opts = {}) {
  let ch = _pool.get(topic);
  if (!ch) { ch = new Channel(topic, opts); _pool.set(topic, ch); }
  else if (opts.meta) ch._meta = { ...ch._meta, ...opts.meta };
  return ch;
}

/** Force a fresh channel (e.g. a demo seeding a mock) — replaces the pooled one. */
export function configureChannel(topic, opts = {}) {
  const prev = _pool.get(topic);
  prev?.close();
  const ch = new Channel(topic, opts);
  _pool.set(topic, ch);
  return ch;
}

// Shared helper: how a child live element finds its Channel.
//
// Priority: an explicit `topic` attribute (opens the pooled channel directly) →
// else the nearest ancestor <live-room>'s channel. Pooling by topic means both
// paths converge on ONE connection per topic. Returns null if neither resolves
// yet (the caller retries on work-room-state / next frame).
import { openChannel } from "./channel.js";

/** Resolve the Channel for `el` (own `topic` attr, else nearest <live-room>). */
export function resolveChannel(el) {
  const topic = el.getAttribute("topic");
  if (topic) return openChannel(topic);
  let p = el.parentElement;
  while (p) {
    if (p.tagName === "LIVE-ROOM") {
      if (p.channel) return p.channel;
      if (typeof p.join === "function") { p.join(); return p.channel; }
    }
    p = p.parentElement;
  }
  return null;
}
